package com.google.javascript.rhino;

import com.google.common.base.Preconditions;
import com.google.javascript.rhino.Token;
import java.io.*;
import java.math.*;
import java.util.*;
import java.util.List;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;

public class IR_tryCatch_TriageGen0Test {

    @Test
    public void testTryCatchSuccess() {
        // Setup: tryBody must be a block
        Node tryBody = IR.block(IR.var(IR.name("x"), IR.number(1)));

        // Setup: catchNode must be a catch node. 
        // Based on the implementation, catchNode.isCatch() must return true.
        // Since we cannot instantiate Node directly with specific types easily without internal knowledge,
        // we use the provided IR factory methods. 
        // IR.catchNode(expr, body) creates a catch node.
        Node catchNode = IR.catchNode(IR.name("e"), IR.block(IR.returnNode()));

        // Execute
        Node result = IR.tryCatch(tryBody, catchNode);

        // Verify
        assertNotNull(result);
        assertEquals(Token.TRY, result.getType());
        assertEquals(tryBody, result.getFirstChild());

        // The second child should be the catch body copied from catchNode
        Node catchBody = result.getNextSibling(); // In Rhino IR, children of TRY are usually tryBody and catchBody
        // Wait, the implementation says: return new Node(Token.TRY, tryBody, catchBody);
        // This means tryBody is child 0 and catchBody is child 1.
        assertEquals(catchBody, result.getChild(1));

        // Verify that catchBody is a copy/derived from catchNode
        // The implementation uses block(catchNode).copyInformationFrom(catchNode)
        // So catchBody should be a block.
        assertEquals(true, result.getChild(1).isBlock());
    }

    @Test(expected = IllegalStateException.class)
    public void testTryCatchFailsWhenTryBodyIsNotBlock() {
        // tryBody is an expression, not a block
        Node tryBody = IR.number(1);
        Node catchNode = IR.catchNode(IR.name("e"), IR.block());

        IR.tryCatch(tryBody, catchNode);
    }

    @Test(expected = IllegalStateException.class)
    public void testTryCatchFailsWhenCatchNodeIsNotCatch() {
        // tryBody is a valid block
        Node tryBody = IR.block();
        // catchNode is a block, but not a "catch" type node
        Node catchNode = IR.block();

        IR.tryCatch(tryBody, catchNode);
    }
}
